-- 0345_schema_migrations_ledger.sql — release QA-2 P0 (2026-09-12)
--
-- Creates the migration ledger this stack never had. Migrations are applied
-- by hand (no auto-apply on deploy); until now nothing recorded which files
-- had actually reached production, which is how 20260814_tech_analyses.sql
-- (projects.github_url) went unapplied for a month and broke project creation.
--
-- From here on:
--   * apply:   scripts/db/apply-migration.sh supabase/migrations/<file>.sql
--              (applies in one transaction, records the row, NOTIFY pgrst)
--   * status:  node scripts/db/migration-status.mjs        (unapplied list)
--   * audit:   node scripts/db/migration-parity.mjs        (live-catalog check)
--   * signal:  GET /api/status → schema_migrations: ok | pending:<n>
--
-- The backfill below was generated from migration-parity.mjs --json after
-- 0344_schema_parity_repair.sql was applied: every file whose objects are all
-- present in the live catalog is recorded as applied; files with no
-- verifiable DDL (data-only seeds, ALTER COLUMN TYPE, dynamic-SQL DO blocks)
-- are recorded as "assumed" — their notes say so. 20260822_investor_portal_core.sql
-- is deliberately NOT recorded (deferred, see scripts/db/parity-exceptions.json).
-- checksum = sha256 of the file at backfill time.

CREATE TABLE IF NOT EXISTS public.schema_migrations (
  filename   text PRIMARY KEY,
  applied_at timestamptz NOT NULL DEFAULT now(),
  checksum   text,
  applied_by text,
  notes      text
);
COMMENT ON TABLE public.schema_migrations IS
  'Ledger of applied SQL migrations (web/supabase/migrations). Written by scripts/db/apply-migration.sh; read by scripts/db/migration-status.mjs and /api/status.';

-- Ops-only table: no anon / authenticated access, RLS on with no policies
-- (service_role bypasses RLS; psql runs as postgres / supabase_admin).
ALTER TABLE public.schema_migrations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.schema_migrations FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON public.schema_migrations TO service_role;

ON CONFLICT (filename) DO NOTHING;

NOTIFY pgrst, 'reload schema';
